        return "evt_000000"

    @contextlib.contextmanager
    def span(
        self,
        start_event: str,
        end_event: str,
        data: dict[str, Any] | None = None,
        **_: Any,
    ) -> Iterator[SpanHandle]:
        yield SpanHandle(self, start_event, end_event)

    @contextlib.contextmanager
