        for record in report.records:
            self.record_count += 1
            event = record["event"]
            data = record["data"]
            self.event_names[event] += 1

            if event == "run_end":
                report.run_end_status = str(data.get("status", "unknown"))
            elif event == "model_request":
                self.model_calls += 1
                self.models[str(data.get("model") or "unknown")] += 1
            elif event == "model_response":
